package com.example.worsi_backend.storage;

import org.springframework.core.io.Resource;

import java.io.IOException;

/**
 * Where image bytes live. Controllers/services depend only on this interface, so the local-disk
 * implementation can be swapped for Cloudinary / S3 / GCS without touching the booking code.
 */
public interface ImageStorage {

    /** Persist {@code data} under {@code key}. Keys are generated by the server, never by the client. */
    void store(String key, byte[] data, String contentType) throws IOException;

    /** Open a stored image. Throws {@link java.io.FileNotFoundException} if the key does not exist. */
    Resource load(String key) throws IOException;

    /** Best-effort removal; must never throw (used in cleanup paths). */
    void deleteQuietly(String key);
}
